package com.shopsphere;import static org.assertj.core.api.Assertions.assertThat;import java.sql.DriverManager;import java.util.UUID;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.testcontainers.containers.MySQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class AuthPersistenceContainerTest{@Container static MySQLContainer<?>mysql=new MySQLContainer<>("mysql:8.4");@Test void profileAndAddressMigrationsPersistData()throws Exception{Flyway.configure().dataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword()).locations("classpath:db/migration").load().migrate();try(var c=DriverManager.getConnection(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());var s=c.prepareStatement("INSERT INTO users(id,first_name,last_name,email,password_hash,role,enabled,created_at,updated_at) VALUES(UUID_TO_BIN(?),'Test','User','test@example.com','hash','CUSTOMER',TRUE,NOW(6),NOW(6))")){var user=UUID.randomUUID();s.setString(1,user.toString());s.executeUpdate();try(var a=c.prepareStatement("INSERT INTO customer_addresses(id,user_id,recipient_name,phone,line1,city,state,postal_code,country,is_default,created_at,updated_at) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),'Test User','9999999999','1 Main','City','State','560001','India',TRUE,NOW(6),NOW(6))")){a.setString(1,UUID.randomUUID().toString());a.setString(2,user.toString());assertThat(a.executeUpdate()).isEqualTo(1);}try(var q=c.createStatement();var rows=q.executeQuery("SELECT COUNT(*) FROM customer_addresses")){rows.next();assertThat(rows.getInt(1)).isEqualTo(1);}}}}
